import time
import smbus2
from functools import partial

ADS1115_I2C_ADDR = 0x48
ADS1115_REG_CONVERSION = 0x00
ADS1115_REG_CONFIG = 0x01

# Configuration register bitmasks and values (see datasheet)
CONFIG_OS_START = 0x8000
CONFIG_OS_PERFORMING_CONVERSION = 0x0000
CONFIG_MUX_AIN0P_GNDN = 0x4000
CONFIG_FSR_4V096 = 0x0200
CONFIG_MODE_SINGLE_SHOT = 0x0100
CONFIG_DATA_RATE_128SPS = 0x0080
CONFIG_COMP_QUE_DISABLE = 0x0003


def swap_endian(word):
    """Swaps the endianness of a 16-bit word."""
    return ((word & 0xff00) >> 8) | ((word & 0x00ff) << 8)


def build_config(channel):
    """Builds the configuration word for a given channel."""
    if not 0 <= channel <= 3:
        raise ValueError("Invalid channel. Must be between 0 and 3.")

    return (
        CONFIG_OS_START
        + CONFIG_MUX_AIN0P_GNDN
        + (channel << 12)
        + CONFIG_FSR_4V096
        + CONFIG_MODE_SINGLE_SHOT
        + CONFIG_DATA_RATE_128SPS
        + CONFIG_COMP_QUE_DISABLE
    )


def read_adc(c):
    """Reads the ADC value from the specified channel."""
    config = build_config(c)
    with smbus2.SMBus(1) as bus:  # Initialize bus here
        try:
            bus.write_word_data(ADS1115_I2C_ADDR, ADS1115_REG_CONFIG, swap_endian(config))

            while True:
                status = swap_endian(bus.read_word_data(ADS1115_I2C_ADDR, ADS1115_REG_CONFIG))
                if (status & CONFIG_OS_START) != CONFIG_OS_PERFORMING_CONVERSION:
                    break

            result = swap_endian(bus.read_word_data(ADS1115_I2C_ADDR, ADS1115_REG_CONVERSION))
            return result
        except Exception as e:
            print(f"Error reading ADC: {e}")
            return None


def run_adc_scan():
    """Scans all ADC channels and prints the values."""
    print("Reading ADS1115 values, press Ctrl-C to quit...")

    while True:
        values = [read_adc(i) for i in range(4)]
        if all(val is not None for val in values):
            print(f"Channel 0: {values[0]}, Channel 1: {values[1]}, Channel 2: {values[2]}, Channel 3: {values[3]}")
        time.sleep(0.05)



if __name__ == "__main__":
    try:
        run_adc_scan()
    except KeyboardInterrupt:
        print("\nExiting...")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

