import time
import board
import busio
import adafruit_max30102

# Constants
I2C_ADDRESS = 0x57
LOG_FILE = "heart_rate_log.txt"
SAMPLE_INTERVAL_SECONDS = 1

def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_sensor(i2c_bus):
    """Initialize the MAX30102 sensor."""
    try:
        return adafruit_max30102.MAX30102(i2c_bus, address=I2C_ADDRESS)
    except Exception as e:
        print(f"Error initializing MAX30102 sensor: {e}")
        return None

def read_sensor_data(sensor):
    """Read heart rate and SpO2 from the sensor."""
    try:
        ir_value = sensor.get_ir()
        red_value = sensor.get_red()
        return ir_value, red_value
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None

def compute_heart_rate(ir_value, red_value):
    """Compute heart rate from IR and RED ADC values."""
    if ir_value is None or red_value is None:
        return None

    # Peak detection to estimate BPM (simplified)
    peaks = []
    for sample in ir_value:
        if sample > 512:  # Threshold for a peak
            peaks.append(sample)
            if len(peaks) > 4:  # Keep only the last 4 peaks
                peaks = peaks[-4:]

    if not peaks:
        return None

    distance_between_peaks = peaks[-1] - peaks[0]
    bpm = 60 / distance_between_peaks
    return int(bpm)

def log_data(timestamp, heart_rate, spo2):
    """Log the data to a file."""
    try:
        with open(LOG_FILE, "a") as logfile:
            logfile.write(f"{timestamp},{heart_rate},{spo2}\n")
    except Exception as e:
        print(f"Error writing to log file: {e}")

def main():
    """Main function to read and log heart rate data."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    sensor = initialize_sensor(i2c_bus)
    if sensor is None:
        return

    try:
        while True:
            timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
            ir_value, red_value = read_sensor_data(sensor)
            heart_rate = compute_heart_rate(ir_value, red_value)

            if heart_rate is not None:
                spo2 = sensor.get_spo2()
                print(f"Heart Rate: {heart_rate} BPM, SpO2: {spo2:.2f}%")
                log_data(timestamp, heart_rate, spo2)
            else:
                print("Could not compute heart rate.")

            time.sleep(SAMPLE_INTERVAL_SECONDS)

    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        # No specific cleanup needed for adafruit_max30102 library
        pass

if __name__ == "__main__":
    main()

