from __future__ import annotations

import atexit
import threading
import time
from typing import Tuple

from flask import Flask, render_template, Response, request

from picamera2 import Picamera2, MappedArray
from picamera2.encoders import JpegEncoder()
from picamera2.outputs import FileOutput

app = Flask(__name__)
picam2 = None
config = None
frame_lock = threading.Lock()
check_for_objects_running = False


def initialize_camera() -> Picamera2:
    """Initialize the camera with error handling and resource management."""
    try:
        cam = Picamera2()
        cam.configure(cam.create_still_configuration(main={"size": (640, 480)}))
        cam.start()
        return cam
    except Exception as e:
        print(f"Camera initialization failed: {e}")
        exit(1)


def capture_frame(cam: Picamera2) -> bytes:
    """Capture a frame from the camera and return it as bytes."""
    with frame_lock:
        array = cam.capture_array()
        if array is None:
            return b""
        return array.to_bytes()


def get_frame(cam: Picamera2) -> bytes:
    """Capture a frame and return it as bytes, handling potential errors."""
    try:
        return capture_frame(cam)
    except Exception as e:
        print(f"Error getting frame: {e}")
        return b""


def get_object(classifier: object) -> Tuple[bytes, bool]:
    """Perform object detection using the provided classifier."""
    try:
        jpeg_bytes, detected = classifier.get_object()
        return jpeg_bytes, detected
    except Exception as e:
        print(f"Object detection error: {e}")
        return b"", False


def get_object_with_basic_motion_detection(classifier: object) -> Tuple[bytes, bool]:
    """Perform object detection with basic motion detection."""
    try:
        # Placeholder for basic motion detection logic
        # This would compare frames to detect changes
        print("Basic motion detection (placeholder)")
        jpeg_bytes, detected = classifier.get_object()
        return jpeg_bytes, detected
    except Exception as e:
        print(f"Motion detection error: {e}")
        return b"", False


def check_for_objects(config: config) -> None:
    """Continuously check for objects based on configuration."""
    global check_for_objects_running
    while check_for_objects_running:
        try:
            classifier = config.classifier_factory(config.classifier_name)
            jpeg_bytes, detected = get_object_with_basic_motion_detection(classifier)

            if detected:
                print(f"Detected object: {config.classifier_name}")
                # Replace with actual email sending implementation
                print("Sending email (placeholder)")
                time.sleep(config.email_send_interval)  # Cooldown period

            time.sleep(1)

        except Exception as e:
            print(f"Error in object checking loop: {e}")
            time.sleep(5)


def start_camera_and_detection_loop(config: config) -> None:
    """Starts the camera and object detection loop in a separate thread."""
    global picam2, check_for_objects_running
    check_for_objects_running = True

    def detection_loop():
        check_for_objects(config)
        check_for_objects_running = False

    if picam2 is None:
        print("Camera not initialized. Exiting.")
        exit(1)

    thread = threading.Thread(target=detection_loop, daemon=True)
    thread.start()


def generate() -> bytes:
    """Generate and return the HTML response."""
    try:
        with FileOutput('video_feed.mjpg', 'wb') as f:
            for _ in range(2):
                frame = get_frame(picam2)
                if frame:
                    f.write(frame)
                time.sleep(0.1)
        return Response(f.read(), mimetype='multipart/x-mixed-replace; boundary=frame')
    except Exception as e:
        print(f"Error generating video feed: {e}")
        return b""


@app.route('/', methods=['GET'])
def index() -> str:
    """Renders the index HTML page."""
    return render_template('index.html', config=config)


@app.route('/video_feed')
def video_feed() -> bytes:
    """Streams the video feed."""
    return generate()


def stop_camera():
    """Stops the camera and releases resources."""
    global picam2
    if picam2:
        picam2.stop()
        picam2.close()
        print("Camera stopped and resources released.")


def register_atexit():
    """Registers the camera stop function to be called on exit."""
    atexit.register(stop_camera)


def main() -> None:
    """Main function to initialize and run the application."""
    global picam2, config
    initialize_camera()
    config = config()
    register_atexit()
    start_camera_and_detection_loop(config)
    app.run(debug=True, host='0.0.0.0')


if __name__ == '__main__':
    main()

