import RPi.GPIO as GPIO
import time
import datetime
import csv
import os
import argparse
from picamera2 import Picamera2

# Define default values
DEFAULT_GPIO = [17, 27, 22]
DEFAULT_LOG_FILE = "/home/pi/vibration_data.csv"
DEFAULT_INTERVAL = 1.0
DEFAULT_CALIBRATION = 60
DEFAULT_PICTURES = 0

def parse_arguments():
    """Parses command-line arguments."""
    parser = argparse.ArgumentParser(description="Vibration monitoring system for manufacturing.")
    parser.add_argument("-g", "--gpio", nargs=3, type=int, default=DEFAULT_GPIO, help="GPIO pins for the sensors (e.g., -g 17 27 22)")
    parser.add_argument("-l", "--log_file", type=str, default=DEFAULT_LOG_FILE, help="Path to the log file (CSV)")
    parser.add_argument("-i", "--interval", type=float, default=DEFAULT_INTERVAL, help="Sampling interval in seconds")
    parser.add_argument("-c", "--calibrate", type=int, default=DEFAULT_CALIBRATION, help="Calibration duration in seconds")
    parser.add_argument("-p", "--pictures", type=int, default=DEFAULT_PICTURES, help="Interval between picture captures in seconds")
    return parser.parse_args()

def setup_gpio(gpio_pins):
    """Sets up the GPIO pins for the sensors."""
    try:
        GPIO.setmode(GPIO.BCM)
        for pin in gpio_pins:
            GPIO.setup(pin, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)  # Use pull-down resistors for stability
        print("GPIO setup complete.")
    except Exception as e:
        print(f"Error setting up GPIO: {e}")
        return False
    return True

def calibrate_sensors(gpio_pins, calibration_duration):
    """Calibrates the sensors and calculates baseline vibration levels."""
    print("Calibrating sensors...")
    sensor_readings = {}
    for pin in gpio_pins:
        sensor_readings[pin] = []
        start_time = time.time()
        while time.time() - start_time < calibration_duration:
            try:
                sensor_readings[pin].append(GPIO.input(pin))
                time.sleep(0.01)  # Short delay to avoid overwhelming the GPIO
            except Exception as e:
                print(f"Error reading sensor {pin}: {e}")
                return False
        sensor_readings[pin] = [1 if reading else 0 for reading in sensor_readings[pin]] # Convert to boolean
    print("Calibration complete.")

    baselines = {}
    for pin in gpio_pins:
        total_high = sum(sensor_readings[pin])
        total_readings = len(sensor_readings[pin])
        if total_readings > 0:
            baselines[pin] = (total_high / total_readings) * 100
        else:
            baselines[pin] = 0
        print(f"Sensor {pin} baseline: {baselines[pin]:.2f}%")

    return baselines

def monitor_sensors(gpio_pins, baselines, interval, log_file):
    """Monitors the sensors and logs the data."""
    try:
        with open(log_file, 'a', newline='') as csvfile:
            writer = csv.writer(csvfile)
            writer.writerow(['Timestamp', 'Sensor1', 'Sensor2', 'Sensor3'])  # Write header if the file is new

            while True:
                start_time = time.time()
                sensor_values = {}
                for pin in gpio_pins:
                    sensor_values[pin] = 0
                    start_time_pin = time.time()
                    while time.time() - start_time_pin < interval:
                        try:
                            sensor_values[pin] += GPIO.input(pin)
                        except Exception as e:
                            print(f"Error reading sensor {pin}: {e}")
                        time.sleep(0.01)  # Short delay to avoid overwhelming the GPIO

                    sensor_values[pin] /= interval  # Average over the interval
                    sensor_values[pin] = max(0, min(1, sensor_values[pin])) # Clamp to 0-1 range

                    if pin in baselines:
                        threshold = baselines[pin] + 20
                        if sensor_values[pin] > threshold:
                            sensor_values[pin] = 1  # Active
                        else:
                            sensor_values[pin] = 0  # Inactive
                    else:
                        sensor_values[pin] = 0  # Inactive, no baseline yet

                timestamp = datetime.datetime.now().isoformat() + "Z"
                writer.writerow([timestamp, int(sensor_values[0]), int(sensor_values[1]), int(sensor_values[2]))]
                csvfile.flush()  # Ensure data is written to disk immediately

                if args.pictures:
                    for pin in gpio_pins:
                        if sensor_values[pin] == 1:
                            image_dir = os.path.join(os.path.dirname(log_file), "images")
                            os.makedirs(image_dir, exist_ok=True) # Create directory if it doesn't exist
                            filename = os.path.join(image_dir, f"{datetime.datetime.now().strftime('%Y-%m-%d_%H-%M-%S')}.jpg")
                            picam2.capture_file(filename)
                            print(f"Captured image: {filename}")

                time.sleep(interval)

    except KeyboardInterrupt:
        print("Monitoring stopped by user.")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        GPIO.cleanup()
        if 'picam2' in locals():
            picam2.close()
        print("GPIO and camera resources cleaned up.")

def main():
    """Main function to run the vibration monitoring system."""
    args = parse_arguments()
    gpio_pins = args.gpio
    log_file = args.log_file
    interval = args.interval
    calibration_duration = args.calibrate
    picture_interval = args.pictures

    if not setup_gpio(gpio_pins):
        print("GPIO setup failed. Exiting.")
        return

    baselines = calibrate_sensors(gpio_pins, calibration_duration)

    if not baselines:
        print("Calibration failed. Exiting.")
        return

    try:
        picam2 = Picamera2()
        picam2.configure(picam2.create_preview_configuration(main={"format": 'XRGB8888', "size": (640, 480)}))
        picam2.start()
    except Exception as e:
        print(f"Camera initialization failed: {e}. Continuing without camera.")

    monitor_sensors(gpio_pins, baselines, interval, log_file)

if __name__ == "__main__":
    main()

