# Configure logging
logging.basicConfig(filename='security_system.log', level=logging.INFO,
                    format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
I2C_ADDRESS = 0x29  # TSL2591 I2C address
BUZZER_PIN = 17  # GPIO pin for the buzzer
LIGHT_THRESHOLD = 25  # Percentage change to trigger an alert
BASELINE_SAMPLE_COUNT = 5  # Number of samples for baseline light level
RETRY_ATTEMPTS = 3  # Number of retries for sensor readings
RETRY_DELAY = 0.5  # Delay between retries in seconds
I2C_RETRY_DELAY = 2  # Delay between I2C bus attempts in seconds
I2C_MAX_ATTEMPTS = 3  # Maximum number of I2C bus attempts

# Global variables
baseline_light_level = 0.0
buzzer = None
bus = None
tsl = None

# Signal handler for graceful shutdown
def signal_handler(sig, frame):
    logging.info("Received signal, shutting down...")
    if buzzer:
        buzzer.off()
    logging.info("Buzzer off.")
    sys.exit(0)

signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

def initialize_i2c():
    """Initializes the I2C bus with retry logic."""
    global bus
    for attempt in range(I2C_MAX_ATTEMPTS):
        try:
            bus = smbus.SMBus(1)  # Use 1 for Raspberry Pi 5
            logging.info("I2C bus initialized successfully.")
            return True
        except Exception as e:
            logging.error(f"Failed to initialize I2C bus (attempt {attempt + 1}/{I2C_MAX_ATTEMPTS}): {e}")
            if attempt < I2C_MAX_ATTEMPTS - 1:
                time.sleep(I2C_RETRY_DELAY)
            else:
                logging.error("Failed to initialize I2C bus after multiple attempts. Exiting.")
                sys.exit(1)
    return False

def initialize_tsl2591():
    """Initializes the TSL2591 light sensor with retry logic."""
    global bus, tsl
    for attempt in range(RETRY_ATTEMPTS):
        try:
            tsl = TSL2591(bus, address=I2C_ADDRESS)
            logging.info("TSL2591 sensor initialized successfully.")
            return True
        except Exception as e:
            logging.error(f"Failed to initialize TSL2591 sensor (attempt {attempt + 1}/{RETRY_ATTEMPTS}): {e}")
            if attempt < RETRY_ATTEMPTS - 1:
                time.sleep(RETRY_DELAY)
            else:
                logging.error("Failed to initialize TSL2591 sensor after multiple attempts. Exiting.")
                return False
    return False

def read_light_level():
    """Reads the light level from the TSL2591 sensor with retry logic."""
    global tsl
    for attempt in range(RETRY_ATTEMPTS):
        try:
            light_level = tsl.lux
            logging.debug(f"Light level: {light_level}")
            return light_level
