import boto3 as b3
import time
import os
import logging
from functools import partial
from typing import Dict, Any, Tuple

from picamera2 import Picamera2, MappedArray

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
COLLECTION_ID = 'home'
IMAGE_PATH = 'image.jpg'
SIMILARITY_THRESHOLD = 85
CAPTURE_DELAY = 2

# Initialize AWS SDK
try:
    rekognition_client = b3.client('rekognition')
except Exception as e:
    logging.error(f"Error initializing AWS SDK: {e}")
    raise


def initialize_camera() -> Picamera2:
    """Initializes the PiCamera2 and applies a warming effect."""
    picam2 = Picamera2()
    picam2.start()
    time.sleep(CAPTURE_DELAY)  # Allow camera to warm up
    return picam2


def capture_image(picam2: Picamera2, image_path: str) -> None:
    """Captures an image from the camera and saves it to the specified path."""
    try:
        array = picam2.capture_array()
        picam2.close()
        os.system(f'wbm {image_path} < {image_path}')
        logging.info(f"Image captured and saved to {image_path}")
    except Exception as e:
        logging.error(f"Error capturing image: {e}")
        raise


def detect_faces(client: b3.client, image_path: str, collection_id: str) -> Tuple[bool, Dict[str, Any]]:
    """Detects faces in the given image using AWS Rekognition."""
    try:
        with open(image_path, 'rb') as image_file:
            response = client.search_faces_by_image(
                CollectionId=collection_id,
                Image={'Bytes': image_file.read()},
                MaxFaces=1,
                FaceMatchThreshold=85
            )
        is_match = bool(response['FaceMatches'])
        return is_match, response
    except ClientError as e:
        logging.error(f"Rekognition client error: {e}")
        return False, {}
    except FileNotFoundError:
        logging.error(f"Image file not found: {image_path}")
        return False, {}
    except Exception as e:
        logging.error(f"Error detecting faces: {e}")
        return False, {}


def process_matches(client: b3.client, image_path: str, collection_id: str) -> Tuple[bool, Dict[str, Any]]:
    """Processes face matches found in the image."""
    is_match, match_results = detect_faces(client, image_path, collection_id)

    if is_match:
        logging.info(f"Matched {len(match_results)} face(s) with similarity {match_results[0]['Similarity']}")
        return True, match_results
    else:
        return False, {}


def main() -> None:
    """Main function to capture an image and search for faces."""
    try:
        picam2 = initialize_camera()
        capture_image(picam2, IMAGE_PATH)

        is_match, match_results = process_matches(rekognition_client, IMAGE_PATH, COLLECTION_ID)

        if is_match:
            matched_id = match_results[0]['Face']['ExternalImageId']
            logging.info(f"Matched with ExternalImageId: {matched_id}")
        else:
            logging.info("No face match found.")

    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        if 'picam2' in locals():
            picam2.close()


if __name__ == '__main__':
    main()

