        bus.write_byte_data(TSL2561_ADDRESS, TSL2561_COMMAND_BIT | TSL2561_CONTROL_REGISTER, 0x03)  # Start measurement, 1x gain, 101ms integration
        time.sleep(0.1)  # Wait for measurement
        return True
    except Exception as e:
        print(f"TSL2561 initialization error: {e}")
        return False

def read_tsl2561():
    """Reads light data from the TSL2561 sensor."""
    try:
        data0_low = bus.read_byte_data(TSL2561_ADDRESS, TSL2561_COMMAND_BIT | TSL2561_DATA0_LOW)
        data0_high = bus.read_byte_data(TSL2561_ADDRESS, TSL2561_COMMAND_BIT | TSL2561_DATA0_HIGH)
        data1_low = bus.read_byte_data(TSL2561_ADDRESS, TSL2561_COMMAND_BIT | TSL2561_DATA1_LOW)
        data1_high = bus.read_byte_data(TSL2561_ADDRESS, TSL2561_COMMAND_BIT | TSL2561_DATA1_HIGH)

        channel0 = (data0_high << 8) | data0_low
        channel1 = (data1_high << 8) | data1_low

        if channel0 > 8192:
            channel0 -= 16384

        if channel1 > 8192:
            channel1 -= 16384

        return channel0, channel1
    except Exception as e:
        print(f"Error reading TSL2561 data: {e}")
        return None, None

def compute_lux(channel0, channel1):
    """Computes lux value from raw sensor data."""
    if channel0 is None or channel1 is None:
        return None

    ratio = channel0 / float(channel0 + channel1)
    if ratio is None:
        return None

    if ratio > 0.52:
        lux = (0.0316 * channel0) - (0.05934 * channel0 * (ratio**1.4))
    elif ratio > 0.18:
        lux = (0.0222 * channel0) - (0.02934 * channel0 * (ratio**1.8))
    else:
        lux = (0.097 * channel0) - (0.257 * channel0 * (ratio**2.45))

    return max(0.0, lux)

def set_oled_brightness(lux):
    """Sets the OLED display brightness based on the lux value."""
    try:
        brightness = min(255, int(lux / 10))
        display.contrast(int(brightness))
    except Exception as e:
        print(f"Error setting OLED brightness: {e}")

def display_lux(lux):
    """Displays the lux value on the OLED screen."""
    try:
        with canvas(display) as draw:
            draw.text((0, 0), f"Lux: {lux:.2f}", fill="white")
    except Exception as e:
        print(f"Error displaying lux: {e}")

def main():
    """Main function to read light and display it."""
    global running, display

    if not initialize_i2c():
        sys.exit(1)
    if not initialize_oled():
        sys.exit(1)
    if not initialize_tsl2561():
        sys.exit(1)

    signal.signal(signal.SIGINT, signal_handler)

    try:
        while running:
            channel0, channel1 = read_tsl2561()
            if channel0 is not None and channel1 is not None:
                lux = compute_lux(channel0, channel1)
                if lux is not None:
                    set_oled_brightness(lux)
                    display_lux(lux)
            time.sleep(1)
    finally:
        # Cleanup resources
        if display:
            display.clear()
        if bus:
            bus.close()
        print("Program finished.")

if __name__ == "__main__":
    main()

