    try:
        display = adafruit_ssd1306.SSD1306_I2C(OLED_WIDTH, OLED_HEIGHT, i2c_bus)
        display.fill(0)
        display.show()
        return display
    except Exception as e:
        print(f"Error initializing OLED: {e}")
        return None

def initialize_dht_sensor(pin):
    """Initialize the DHT22 sensor."""
    try:
        dht_sensor = adafruit_dht.DHT22(pin)
        return dht_sensor
    except Exception as e:
        print(f"Error initializing DHT22 sensor: {e}")
        return None

def read_sensor_data(dht_sensor):
    """Read temperature and humidity from the DHT22 sensor."""
    try:
        for _ in range(RETRY_COUNT):
            try:
                temperature_c = dht_sensor.temperature
                humidity_percent = dht_sensor.humidity
                if temperature_c is not None and humidity_percent is not None:
                    return temperature_c, humidity_percent
                else:
                    print("Failed to read sensor data. Retrying...")
                    time.sleep(1)
            except RuntimeError as e:
                print(f"Error reading DHT22 sensor: {e}. Retrying...")
                time.sleep(1)
            except Exception as e:
                print(f"Unexpected error reading sensor: {e}")
                return None, None
        print("Failed to read sensor data after multiple retries.")
        return None, None
    except Exception as e:
        print(f"Unexpected error reading sensor: {e}")
        return None, None

def display_data(display, temperature, humidity):
    """Display temperature and humidity on the OLED screen."""
    try:
        display.fill(0)
        display.text(f"Temp: {temperature:.1f}C", 0, 0, 1)
        display.text(f"Humidity: {humidity:.1f}%", 0, 16, 1)
        display.show()
    except Exception as e:
        print(f"Error displaying data: {e}")

