    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    oled_display = initialize_oled(i2c_bus)
    if oled_display is None:
        i2c_bus.deinit()
        return

    dht_sensor = initialize_dht_sensor(DHT_PIN)
    if dht_sensor is None:
        i2c_bus.deinit()
        return

    try:
        while True:
            temperature, humidity = read_sensor_data(dht_sensor)
            if temperature is not None and humidity is not None:
                display_data(oled_display, temperature, humidity)
            else:
                print("Failed to read sensor data. Retrying...")
                time.sleep(SLEEP_INTERVAL)
            time.sleep(SLEEP_INTERVAL)
    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        oled_display.fill(0)
        oled_display.show()
        i2c_bus.deinit()
        print("I2C bus deinitialized.")

if __name__ == "__main__":
    main()

