# temperature_sensor_uart_rpi.py
# Reads temperature data from an RS485 sensor via UART on a Raspberry Pi.

import serial
import time

# Serial port configuration for the USB-to-RS485 adapter
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 115200
DATA_BITS = serial.EIGHTBITS
PARITY = serial.PARITY_NONE
STOP_BITS = serial.STOPBITS_ONE
TIMEOUT = 1  # seconds

def read_temperature_data():
    """Reads a line from the serial port and extracts the temperature value."""
    try:
        with serial.Serial(SERIAL_PORT, BAUD_RATE, bytesize=8, parity=PARITY, stopbits=STOP_BITS, timeout=TIMEOUT) as ser:
            while True:
                try:
                    line = ser.readline().decode('ascii', errors='replace').strip()
                    if line:
                        temperature_value = float(line.split('=')[1].strip())
                        print(f'Temperature: {temperature_value:.1f} C')
                except ValueError:
                    print("Error: Could not parse temperature data.")
                except Exception as e:
                    print(f"Error reading from serial port: {e}")
                time.sleep(0.5)
    except serial.SerialException as e:
        print(f"Error opening serial port {SERIAL_PORT}: {e}")
    except KeyboardInterrupt:
        print("Program terminated by user.")

if __name__ == "__main__":
    read_temperature_data()

