import socket
import json
import time
import logging
import argparse
import random

# Configure logging
logging.basicConfig(filename='hydroponics.log', level=logging.INFO,
                    format='%(asctime)s - %(levelname)s - %(message)s')

def setup_gpio(relay_pin, dht_pin):
    """Sets up the GPIO pins for the relay and DHT sensor."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(relay_pin, GPIO.OUT)
        GPIO.output(relay_pin, GPIO.LOW)  # Initialize relay to OFF
        logging.info(f"GPIO setup complete: relay_pin={relay_pin}, dht_pin={dht_pin}")
    except Exception as e:
        logging.error(f"GPIO setup failed: {e}")
        raise

def read_dht11(dht_pin):
    """Simulates reading temperature from a DHT11 sensor."""
    # In a real implementation, this would read from the DHT11 sensor.
    # For simulation, return a fixed temperature.
    temperature = 25.0  # Fixed temperature for simulation
    logging.info(f"Simulated DHT11 reading: temperature={temperature}")
    return temperature

def set_relay_state(relay_pin, state):
    """Sets the state of the relay (ON or OFF)."""
    try:
        GPIO.output(relay_pin, GPIO.HIGH if state == "ON" else GPIO.LOW)
        logging.info(f"Relay set to: {state}")
    except Exception as e:
        logging.error(f"Relay control failed: {e}")

def handle_client(conn, addr):
    """Handles a client connection and processes commands."""
    logging.info(f"Accepted connection from {addr}")
    try:
        while True:
            data = conn.recv(1024)
            if not data:
                break

            try:
                command = json.loads(data.decode())
                logging.info(f"Received command: {command}")

                if command["command"] == "pump_on":
                    set_relay_state(PUMP_RELAY_PIN, "ON")
                    response = {"status": "success", "pump": "on"}
                elif command["command"] == "pump_off":
                    set_relay_state(PUMP_RELAY_PIN, "OFF")
                    response = {"status": "success", "pump": "off"}
                elif command["command"] == "get_status":
                    temperature = read_dht11(DHT11_PIN)
                    response = {"status": "success", "pump": pump_state, "temperature": temperature}
                else:
                    response = {"status": "error", "message": "Invalid command"}

                conn.sendall(json.dumps(response).encode())
            except json.JSONDecodeError:
                response = {"status": "error", "message": "Invalid JSON"}
                conn.sendall(json.dumps(response).encode())
            except Exception as e:
                logging.error(f"Error handling command: {e}")
                response = {"status": "error", "message": "Internal server error"}
                conn.sendall(json.dumps(response).encode())

    except Exception as e:
        logging.error(f"Error handling client: {e}")
    finally:
        conn.close()
        logging.info(f"Connection closed with {addr}")

def main():
    """Main function to run the hydroponics controller."""
    parser = argparse.ArgumentParser(description="Hydroponics Controller")
    parser.add_argument("--relay_pin", type=int, default=RELAY_PIN, help="GPIO pin for the relay")
    parser.add_argument("--dht_pin", type=int, default=DHT11_PIN, help="GPIO pin for the DHT11 sensor")
    parser.add_argument("--port", type=int, default=PORT, help="Port number for the TCP socket")
    parser.add_argument("--allowed_ip", type=str, default="192.168.1.100", help="Allowed IP address for connections")
    parser.add_argument("--log_file", type=str, default="hydroponics.log", help="Path to the log file")
    args = parser.parse_args()

    try:
        setup_gpio(args.relay_pin, args.dht_pin)
        server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)  # Allow reuse of the address
        server_socket.bind((args.port, args.allowed_ip))
        server_socket.listen(1)
        logging.info(f"Server listening on port {args.port}")

        while True:
            conn, addr = server_socket.accept()
            handle_client(conn, addr)

    except Exception as e:
        logging.error(f"Server error: {e}")
    finally:
        if 'server_socket' in locals():
            server_socket.close()
        GPIO.cleanup()
        logging.info("Hydroponics controller stopped.")

if __name__ == "__main__":
    main()

