import serial
import time
import csv
import os

# Configuration
SERIAL_PORT = '/dev/ttyACM0'
BAUD_RATE = 115200
TIMEOUT = 1
CSV_FILE = 'temperature_log.csv'

def initialize_serial(port, baudrate, timeout):
    """Initializes the serial connection."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def read_temperature_data(serial_connection):
    """Reads temperature data from the serial port."""
    try:
        line = serial_connection.readline().decode('ascii', errors='replace').strip()
        if line:
            return line
        return None
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}")
        return None

def convert_to_fahrenheit(celsius_value):
    """Converts Celsius to Fahrenheit."""
    return celsius_value * 9/5 + 32

def log_temperature_data(csv_file, timestamp, celsius_value, fahrenheit_value):
    """Logs the temperature data to a CSV file."""
    try:
        with open(csv_file, 'a', newline='') as csvfile:
            writer = csv.writer(csvfile)
            if csvfile.tell() == 0:  # Check if the file is empty to write the header
                writer.writerow(['Timestamp', 'Celsius', 'Fahrenheit'])
            writer.writerow([timestamp, celsius_value, fahrenheit_value])
    except IOError as e:
        print(f"Error writing to CSV file: {e}")

def main():
    """Main function to read, convert, and log temperature data."""
    serial_connection = initialize_serial(SERIAL_PORT, BAUD_RATE, TIMEOUT)

    if serial_connection is None:
        print("Failed to initialize serial connection. Exiting.")
        return

    try:
        while True:
            temperature_data = read_temperature_data(serial_connection)

            if temperature_data:
                try:
                    celsius_value = float(temperature_data)
                    fahrenheit_value = convert_to_fahrenheit(celsius_value)
                    timestamp = time.strftime('%Y-%m-%d %H:%M:%S')

                    log_temperature_data(CSV_FILE, timestamp, celsius_value, fahrenheit_value)
                    print(f"Logged: {timestamp}, {celsius_value}C = {fahrenheit_value}F")

                except ValueError:
                    print(f"Warning: Invalid data received: {temperature_data}")

            time.sleep(1)  # Prevent busy-waiting

    except KeyboardInterrupt:
        print("Program terminated by user.")

    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

