import RPi.GPIO as GPIO
import time

# Define GPIO pin for DHT22 data line
DHT_PIN = 4

# Initialize GPIO
GPIO.setmode(GPIO.BCM)
GPIO.setup(DHT_PIN, GPIO.OUT)

def read_dht22():
    """Reads temperature and humidity from DHT22 sensor."""
    GPIO.output(DHT_PIN, GPIO.LOW)
    time.sleep(0.018)
    GPIO.output(DHT_PIN, GPIO.HIGH)
    GPIO.setup(DHT_PIN, GPIO.IN)

    # Wait for sensor to pull data line low
    timeout = time.time() + 0.1  # 100ms timeout
    while GPIO.input(DHT_PIN) == GPIO.HIGH:
        if time.time() > timeout:
            return None, None
    return read_dht22()

def read_dht22_data():
    """Reads and processes DHT22 data."""
    data = []
    pulse_start = time.time()
    pulse_end = time.time()

    # Wait for start signal (low for 80ms)
    timeout = time.time() + 0.1  # 100ms timeout
    while GPIO.input(DHT_PIN) == GPIO.HIGH:
        if time.time() > timeout:
            return None, None

    # Wait for data to start (high for 80ms)
    timeout = time.time() + 0.1  # 100ms timeout
    while GPIO.input(DHT_PIN) == GPIO.LOW:
        if time.time() > timeout:
            return None, None

    # Read data bits
    for _ in range(40):
        pulse_start = time.time()
        pulse_end = time.time()
        while GPIO.input(DHT_PIN) == GPIO.LOW:
            pulse_start = time.time()
        while GPIO.input(DHT_PIN) == GPIO.HIGH:
            pulse_end = time.time()

        pulse_duration = pulse_end - pulse_start
        data.append(pulse_duration > 0.00005)  # 50us

    # Convert data to bytes
    bytes_ = []
    for i in range(0, 40, 8):
        byte = 0
        for j in range(8):
            byte <<= 1
            if data[i + j]:
                byte |= 1
        bytes_.append(byte)

    # Checksum validation
    checksum = bytes_[0] & 0xFF
    if bytes_[1] + bytes_[2] + bytes_[3] + checksum & 0xFF != bytes_[4]:
        return None, None

    humidity = bytes_[2] + (bytes_[3] / 10)
    temperature = bytes_[0] + (bytes_[1] / 10)
    return temperature, humidity

def main():
    """Main function to read and display sensor data."""
    try:
        while True:
            temperature, humidity = read_dht22_data()

            if temperature is not None and humidity is not None:
                print(f"Temperature: {temperature:.1f}°C")
                print(f"Humidity: {humidity:.1f}%")
            else:
                print("Failed to read sensor data.")

            time.sleep(5)

    except KeyboardInterrupt:
        print("Exiting program.")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        GPIO.cleanup()

if __name__ == "__main__":
    main()

