import time
import board
import busio
import adafruit_bmp280

# Configuration
I2C_BUS = 1
BMP280_ADDRESS = 0x76  # Default address, can be 0x77 on some boards
BASELINE_READINGS = 10
BASELINE_INTERVAL = 1
ALTITUDE_READ_INTERVAL = 1

def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA, clock_speed=100000)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_bmp280(i2c_bus):
    """Initialize the BMP280 sensor."""
    try:
        return adafruit_bmp280.BMP280_I2C(i2c_bus, address=BMP280_ADDRESS)
    except Exception as e:
        print(f"Error initializing BMP280: {e}")
        return None

def collect_baseline_pressure(sensor, num_readings, interval):
    """Collect baseline pressure readings over a specified interval."""
    baseline_values = []
    print(f"Collecting baseline pressure for {num_readings} seconds...")
    for _ in range(num_readings):
        try:
            pressure = sensor.pressure
            baseline_values.append(pressure)
            time.sleep(interval)
        except OSError as e:
            print(f"Error reading pressure during baseline collection: {e}")
            continue  # Skip problematic reading
    return baseline_values

def calculate_average_baseline(baseline_values):
    """Calculate the average baseline pressure, excluding the first two readings."""
    if len(baseline_values) < 2:
        return sum(baseline_values) / len(baseline_values) if baseline_values else 0  # Return average of available readings

    # Exclude the first two readings to account for sensor warm-up
    baseline_values = baseline_values[2:]
    return sum(baseline_values) / len(baseline_values)

def calculate_altitude(pressure, baseline_pressure):
    """Calculate relative altitude based on pressure and baseline pressure."""
    if baseline_pressure == 0:  # Handle potential division by zero
        return 0
    return 44330 * (1 - (pressure / baseline_pressure))

def main():
    """Main function to read and display altitude."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    bmp280 = initialize_bmp280(i2c_bus)
    if bmp280 is None:
        return

    baseline_readings = collect_baseline_pressure(bmp280, BASELINE_READINGS, ALTITUDE_READ_INTERVAL)
    baseline_pressure = calculate_average_baseline(baseline_readings)

    try:
        while True:
            try:
                pressure = bmp280.pressure
                altitude = calculate_altitude(pressure, baseline_pressure)
                print(f'Relative altitude: {altitude:.2f} meters')
                time.sleep(ALTITUDE_READ_INTERVAL)
            except OSError as e:
                print(f"Error reading pressure: {e}")
                time.sleep(ALTITUDE_READ_INTERVAL)  # Wait before retrying
    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        # No specific cleanup needed for I2C or BMP280 in this library
        print("Program finished.")

if __name__ == "__main__":
    main()

