# environmental_sensor_alerts.py
# Reads temperature and humidity from a UART sensor and alerts on thresholds.
import serial
import time

SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TEMPERATURE_THRESHOLD = 30.0
HUMIDITY_THRESHOLD = 70.0

def read_sensor_line(serial_connection):
    """Read one line from the serial port and decode it."""
    try:
        line = serial_connection.readline().decode('ascii', errors='replace').strip()
        return line
    except serial.SerialException as serial_error:
        print("Serial read error:", serial_error)
        return None

def parse_fields(line):
    """Split a comma-separated line into temperature and humidity."""
    if not line:
        return None, None
    try:
        temperature, humidity = line.split(',')
        return float(temperature), float(humidity)
    except ValueError:
        print("Malformed line:", line)
        return None, None

def evaluate_thresholds(temperature, humidity):
    """Print an alert if thresholds are exceeded."""
    if temperature is not None and humidity is not None:
        print("Temperature:", temperature, "C")
        print("Humidity:", humidity, "%")
        if temperature > TEMPERATURE_THRESHOLD or humidity > HUMIDITY_THRESHOLD:
            print("ALERT: High temp or humidity")

def main():
    """Open the serial port and continuously read the sensor."""
    serial_connection = None
    try:
        # Open the serial port for the environmental sensor
        serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=1)
        print("Sensor connected on", SERIAL_PORT)
        while True:
            line = read_sensor_line(serial_connection)
            temperature, humidity = parse_fields(line)
            evaluate_thresholds(temperature, humidity)
            if temperature is not None and humidity is not None:
                time.sleep(1)
            else:
                print("Skipping bad reading")
                time.sleep(1)
    except serial.SerialException as serial_error:
        print("Could not open serial port:", serial_error)
    except KeyboardInterrupt:
        print("Stopping sensor reader")
    finally:
        # Always close the serial port
        if serial_connection is not None:
            serial_connection.close()
            print("Serial port closed")

if __name__ == "__main__":
    main()

