# Thermal imaging viewer for Raspberry Pi using UART and matplotlib
# Reads frames from a serial thermal camera and displays them as heat maps
import serial
import time
import numpy as np
import matplotlib.pyplot as plt

SERIAL_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600
FRAME_WIDTH = 24
FRAME_HEIGHT = 32
SERIAL_TIMEOUT = 1.0

def open_serial_port(port, baud, timeout):
    """Open and configure the serial port."""
    try:
        return serial.Serial(port, baud, timeout=timeout, parity='N', stopbits=1, bytesize=8, timeout=SERIAL_TIMEOUT)
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def read_thermal_frame(serial_connection):
    """Read a single thermal frame from the serial port."""
    try:
        line = serial_connection.readline().decode('ascii', errors='replace').strip()
        if not line:
            return None
        return [int(token) for token in line.split(',') if token]  # Parse comma-separated values
    except ValueError as e:
        print(f"Error parsing frame: {e}")
        return None
    except Exception as e:
        print(f"Error reading frame: {e}")
        return None

def validate_frame(frame_data):
    """Validate that a frame contains the correct number of pixels."""
    if len(frame_data) != FRAME_WIDTH * FRAME_HEIGHT:
        print("Invalid frame size.")
        return False
    return True

def update_heatmap(heatmap, frame_data):
    """Update the heatmap with new pixel data, handling invalid frames."""
    if validate_frame(frame_data):
        heatmap.set_data(np.array(frame_data).reshape((FRAME_HEIGHT, FRAME_WIDTH)))
    return heatmap

def main():
    """Main function to read thermal frames and display them."""
    serial_connection = open_serial_port(SERIAL_PORT, BAUD_RATE, SERIAL_TIMEOUT)
    if serial_connection is None:
        return

    try:
        plt.ion()  # Interactive mode for live updates
        fig, ax = plt.subplots()
        heatmap = ax.imshow(np.zeros((FRAME_HEIGHT, FRAME_WIDTH)), cmap='inferno', interpolation='nearest')
        plt.draw()
        plt.pause(0.001)  # Initial draw

        while True:
            frame_data = read_thermal_frame(serial_connection)
            if frame_data:
                update_heatmap(heatmap, frame_data)
                plt.pause(0.1)  # Refresh loop
    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        serial_connection.close()
        plt.close('all')

if __name__ == "__main__":
    main()

