import sys
import threading
import RPi.GPIO as GPIO
import DOGProtocol as DOG  # Assuming this module exists

# Constants
DEFAULT_LOG_FILE = "data.log"
POLL_INTERVAL = 0.1  # seconds
MAX_LOG_SIZE = 10 * 1024 * 1024  # 10MB

# Global variables
server_running = False
log_file_path = DEFAULT_LOG_FILE
log_file = None
receive_thread = None
receive_lock = threading.Lock()
stop_event = threading.Event()


def initialize_gpio():
    """Initializes GPIO settings.  Handles potential errors during initialization."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setwarnings(False)  # Suppress warnings in production
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        sys.exit(1)


def cleanup_gpio():
    """Cleans up GPIO resources.  Ensures proper cleanup on exit."""
    try:
        GPIO.cleanup()
    except Exception as e:
        print(f"Error cleaning up GPIO: {e}")


def write_to_log(message):
    """Writes a message to the log file with proper synchronization and file size limitation."""
    global log_file

    if log_file is None:
        return  # Log file not initialized

    try:
        if log_file.tell() + len(message) > MAX_LOG_SIZE:
            log_file.seek(0)  # Rewind to the beginning of the file
            log_file.truncate()  # Clear the file

        log_file.write(message)
        log_file.flush()  # Ensure data is written to disk immediately
    except Exception as e:
        print(f"Error writing to log file: {e}")


def receive_loop():
    """Continuously receives data and writes it to the log file."""
    global receive_thread, stop_event

    while not stop_event.is_set():
        try:
            data = DOG.receive()  # Placeholder for actual receive function
            if data:  # Check if data is not empty
                with receive_lock:
                    write_to_log(data)
        except Exception as e:
            print(f"Error in receive loop: {e}")
            break  # Exit loop on error
    print("Receive thread stopped.")


def start_server():
    """Starts the data logging server."""
    global server_running, log_file, receive_thread, stop_event

    initialize_gpio()
    log_file = open(log_file_path, "a+",  # Open in append mode, allow writing at current position
                    buffering=1,  # Line buffering
                    encoding="utf-8")  # Ensure proper encoding

    try:
        receive_thread = threading.Thread(target=receive_loop, name="ReceiveThread")
        receive_thread.daemon = True  # Allow main thread to exit even if this is running
        receive_thread.start()

        print("Server started. Press Ctrl+C to stop.")
        while True:
            command = input("JAYES@ROVER53:\t")
            if command.lower() == "help":
                display_help()
            elif command.lower() == "start":
                if log_file.name != log_file_path:  # Check if log file was already opened
                    log_file.close()
                start_command = command.split()[1]
                if start_command:
                    try:
                        DOG.send(start_command)  # Placeholder for actual send function
                        print(f"Sent: {start_command}")
                    except Exception as e:
                        print(f"Error sending data: {e}")
                else:
                    print("Start command required.")
            elif command.lower() == "stop":
                stop_event.set()
                break
            elif command.lower() == "exit":
                stop_event.set()
                break
            elif command.lower() == "display":
                if log_file.name != log_file_path:
                    log_file.close()
                try:
                    with open(log_file_path, "r") as f:
