import time
import board
import busio
import adafruit_tsl2561
import RPi.GPIO as GPIO
from gpiozero import PWMLED

# Constants
LED_GPIO_PIN = 18
PWM_FREQUENCY = 1000
I2C_ADDRESS = 0x39
SLEEP_INTERVAL = 1

def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_light_sensor(i2c_bus):
    """Initialize the TSL2561 light sensor."""
    try:
        return adafruit_tsl2561.TSL2561(i2c_bus, address=I2C_ADDRESS)
    except Exception as e:
        print(f"Error initializing TSL2561: {e}")
        return None

def initialize_led(pin, frequency):
    """Initialize the LED with PWM."""
    try:
        led = PWMLED(pin, frequency)
        return led
    except Exception as e:
        print(f"Error initializing LED: {e}")
        return None

def read_light_intensity(sensor):
    """Read light intensity from the sensor."""
    try:
        return sensor.lux
    except Exception as e:
        print(f"Error reading light intensity: {e}")
        return None

def map_intensity_to_brightness(lux_value):
    """Map lux value to brightness (0-100)."""
    if lux_value is None:
        return 0
    return min(max(int(lux_value / 10), 0), 100)

def update_led_brightness(led, brightness):
    """Set the LED brightness."""
    try:
        led.value = brightness
    except Exception as e:
        print(f"Error setting LED brightness: {e}")

def main():
    """Main function to read light and control LED."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    light_sensor = initialize_light_sensor(i2c_bus)
    if light_sensor is None:
        return

    led = initialize_led(LED_GPIO_PIN, PWM_FREQUENCY)
    if led is None:
        return

    try:
        while True:
            lux = read_light_intensity(light_sensor)
            brightness = map_intensity_to_brightness(lux)
            update_led_brightness(led, brightness)
            print(f"Light Intensity: {lux} lux, LED Brightness: {brightness}%")
            time.sleep(SLEEP_INTERVAL)
    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        # Cleanup resources
        led.close()
        GPIO.cleanup()
        if i2c_bus:
            i2c_bus.deinit()

if __name__ == "__main__":
    main()

