@app.route('/light_on')
def light_on():
    """Turn the LED on and return a confirmation message."""
    if led is None:
        return "Error: LED could not be initialized.", 500
    led.on()
    return render_template_string('<h1>LED is now ON</h1><a href="/">Back</a>')

# Route to turn the LED off
@app.route('/light_off')
def light_off():
    """Turn the LED off and return a confirmation message."""
    if led is None:
        return "Error: LED could not be initialized.", 500
    led.off()
    return render_template_string('<h1>LED is now OFF</h1><a href="/">Back</a>')

