import RPi.GPIO as GPIO
import time
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants for GPIO pin numbers (BCM numbering)
DATA_OUT_PIN = 5
TIMER_OUT_PIN = 6
DATA_IN_PIN = 20
TIMER_IN_PIN = 21

# Protocol Constants
START_SIGNAL = [1, 0, 1, 1, 1, 1, 1, 1]
END_SIGNAL = [1, 1, 1, 1, 1, 1, 1, 1]
BASE_BUFFER = [0, 0, 0, 0, 0, 0, 0, 0]

# Timing constants (seconds)
TRANSMIT_DELAY = 0.0005
RECEPTION_TIMEOUT = 1  # Timeout in seconds for reception


class GPIOError(Exception):
    """Custom exception for GPIO related errors."""
    pass


class ProtocolError(Exception):
    """Custom exception for data protocol errors."""
    pass


def initialize_gpio():
    """Initializes GPIO pins and sets their modes."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(DATA_OUT_PIN, GPIO.OUT, initial=0)
        GPIO.setup(TIMER_OUT_PIN, GPIO.OUT, initial=0)
        GPIO.setup(DATA_IN_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        GPIO.setup(TIMER_IN_PIN, GPIO.IN, pull_up_down=GPIO.PUD_DOWN)
        logging.info("GPIO initialization successful.")
    except Exception as e:
        raise GPIOError(f"GPIO initialization failed: {e}") from e


def char_to_buffer(char: str) -> list[int]:
    """Converts a character to a buffer (list of 8 bits)."""
    if not isinstance(char, str) or len(char) != 1:
        raise TypeError("Input must be a single character string.")

    ascii_value = ord(char)
    return [0] + [int(bit) for bit in bin(ascii_value)[2:].zfill(7)]


def buffer_to_char(buffer: list[int]) -> str:
    """Converts a buffer (list of 8 bits) to a character."""
    if not isinstance(buffer, list) or len(buffer) != 8 or not all(isinstance(bit, int) for bit in buffer):
        raise TypeError("Input must be a list of 8 integers.")

    return chr(int("".join(map(str, buffer[1:])), 2))


def string_to_buffer_list(input_string: str) -> list[list[int]]:
    """Converts a string to a list of buffers."""
    if not isinstance(input_string, str):
        raise TypeError("Input must be a string.")
    return [char_to_buffer(char) for char in input_string]


def buffer_list_to_string(buffer_list: list[list[int]]) -> str:
    """Converts a list of buffers to a string."""
    if not isinstance(buffer_list, list):
        raise TypeError("Input must be a list.")
    return "".join(buffer_to_char(buffer) for buffer in buffer_list if buffer not in (START_SIGNAL, END_SIGNAL))


def transmit_bit(bit: int):
    """Transmits a single bit."""
    try:
        GPIO.output(TIMER_OUT_PIN, GPIO.LOW)
        GPIO.output(DATA_OUT_PIN, bit)
        time.sleep(TRANSMIT_DELAY)
        GPIO.output(TIMER_OUT_PIN, GPIO.HIGH)
        time.sleep(TRANSMIT_DELAY)
        GPIO.output(TIMER_OUT_PIN, GPIO.LOW)
    except Exception as e:
        raise GPIOError(f"Bit transmission failed: {e}") from e


def send_data(data_string: str):
    """Sends a string over the data protocol."""
    try:
        initialize_gpio()
        buffer_list = string_to_buffer_list(data_string)
        for buffer in buffer_list:
            for bit in buffer:
                transmit_bit(bit)
            time.sleep(0.002)  # Small delay between buffers
        logging.info(f"Sent data: {data_string}")
    except GPIOError as e:
        raise
    finally:
        GPIO.cleanup()  # Clean up GPIO in the finally block


def receive_data() -> str:
    """Receives data over the data protocol."""
    try:
        initialize_gpio()
        received_buffers = [START_SIGNAL]
        current_buffer = list(BASE_BUFFER)  # Create a copy

        # Wait for start signal
        while True:
            while GPIO.input(TIMER_IN_PIN) == GPIO.LOW:
                pass
            received_buffers.append(current_buffer)
            while GPIO.input(TIMER_IN_PIN) == GPIO.HIGH:
                pass
            current_buffer[:] = list(BASE_BUFFER)
            while GPIO.input(TIMER_IN_PIN) == GPIO.LOW:
                pass

        # Receive data
        while received_buffers[-1] != END_SIGNAL:
            for bit in received_buffers[-1]:
                while GPIO.input(TIMER_IN_PIN) == GPIO.LOW:
                    pass
                current_buffer[0] = GPIO.input(DATA_IN_PIN)
                while GPIO.input(TIMER_IN_PIN) == GPIO.HIGH:
                    pass
            received_buffers.append(current_buffer)
            while GPIO.input(TIMER_IN_PIN) == GPIO.LOW:
                pass

        buffer_list = [buffer for buffer in received_buffers[1:] if buffer not in (START_SIGNAL, END_SIGNAL)]
        return buffer_list_to_string(buffer_list)

    except GPIOError as e:
        raise
    except Exception as e:
        raise ProtocolError(f"Data reception failed: {e}") from e
    finally:
        GPIO.cleanup()


if __name__ == "__main__":
    try:
        send_data("Hello, world!")
        received_string = receive_data()
        logging.info(f"Received: {received_string}")

    except (GPIOError, ProtocolError) as e:
        logging.error(f"An error occurred: {e}")
    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    finally:
        GPIO.cleanup()

