                else:
                    GPIO.output(10, GPIO.LOW)
            except Exception as e:
                self.logger.error(f"Failed to control GPIO: {e}")

    def handle_message(self, data):
        """Processes incoming data and updates PID controller."""
        self.last_msg = time.time()
        if data['type'] == 'STATUS':
            pass  # No action for STATUS messages
        elif data['type'] == 'RESET':
            self.global_err_state = False
            self.logger.info("PID error state reset.")
        elif data['type'] == 'SUBSCRIPTION':
            self.logger.info(f"Subscribed to: {data['stream_filter']}, channel_id: {data['id']}")
        elif data['type'] == 'UNSUBSCRIPTION':
            self.logger.info(f"Unsubscribed from: {data['stream_filter']}, channel_id: {data['id']}")
        elif data['type'] == 'RESET_ALL':
            self.global_err_state = False
            self.logger.info("PID error state reset for all channels.")
        elif data['type'] == 'UPDATE_KW':
            pass # No action needed for UPDATE_KW
        elif data['type'] == 'SET_KW':
            self.config[data['stream_filter']] = data
            self.logger.info(f"Configuration updated for stream filter: {data['stream_filter']}")
        elif data['type'] == 'UPDATE_PIDs':
            if data['stream_filter'] not in self.config:
                self.logger.warning(f"Unknown stream filter: {data['stream_filter']}")
                return

            for i, pid in enumerate(data['pids']):
                if pid['id'] not in self.config[data['stream_filter']]:
                    self.logger.warning(f"Unknown PID id: {pid['id']} for stream filter: {data['stream_filter']}")
                    continue

                try:
                    pid_config = self.config[data['stream_filter']][pid['id']]
                    pid_instance = type(pid_config['T'])((pid_config['Kp'], pid_config['Ki'], pid_config['Kd']),
                                                            (pid_config['Vr'], pid_config['Voffset']),
                                                            pid_config['Integral'], pid_config['AntiWindupTime'])
                    pid_instance.update(data)
                    self.config[data['stream_filter']][pid['id']] = pid_instance
                except Exception as e:
                    self.logger.exception(f"Error updating PID for channel {pid['id']}: {e}")

        self.update_error_output(self.global_err_state)

    def cleanup(self):
        """Releases GPIO resources."""
        if self.pwm:
            try:
                self.pwm.stop()
            except Exception as e:
                self.logger.error(f"Error stopping PWM: {e}")
        try:
            GPIO.cleanup()  # Cleanup all GPIO pins
        except Exception as e:
            self.logger.error(f"Error cleaning up GPIO: {e}")


class SubscriptionHandlerThread(threading.Thread):
    """Handles subscriptions and processes incoming data in a separate thread."""

    def __init__(self, subscription_handler, logger):
        threading.Thread.__init__(self)
        self.subscription_handler = subscription_handler
        self.logger = logger
        self.sub_list = {}
        self.running = True

    def run(self):
        """Runs the subscription handling loop."""
        self.sub_list = self.subscription_handler.sub_list
        while self.running:
            try:
                data = self.subscription_handler.sub_list['control'].get()
                if data is not None:
                    self.process_data(data)
            except KeyError:
                pass  # Handle missing data gracefully
            except Exception as e:
                self.logger.exception(f"Error in subscription thread: {e}")
            finally:
                time.sleep(0.1)  # Adjust sleep time as needed

    def process_data(self, data):
        """Processes incoming data and calls appropriate callbacks."""
        if data['type'] == 'UPDATE_KW':
            self.update_keywords(data)
        elif data['type'] == 'SUBSCRIPTION':
            self.add_subscription(data)
        elif data['type'] == 'RESET_ALL':
            self.reset_all_channels()
        elif data['type'] == 'RESET_CHANNEL':
            self.reset_channel(data)
        elif data['type'] == 'UNSUBSCRIPTION':
            self.remove_subscription(data)
        elif data['type'] == 'STATUS':
            pass
        else:
            self.logger.warning(f"Unknown data type: {data['type']}")
            return

    def update_keywords(self, data):
        """Updates the keywords for a specific stream filter."""
        self.subscription_handler.handle_command(data, self.sub_list)

    def add_subscription(self, data):
        """Adds a new subscription."""
        self.subscription_handler.handle_command(data, self.sub_list)

    def reset_all_channels(self):
        """Resets the state of all channels for a specific stream filter."""
        self.subscription_handler.handle_command({'action': 'RESET_ALL'}, self.sub_list)

    def reset_channel(self, data):
        """Resets the state of a specific channel."""
        self.subscription_handler.handle_command({'action': 'RESET_CHANNEL', 'stream_filter': data['stream_filter'], 'id': data['id']}, self.sub_list)

    def remove_subscription(self, data):
        """Removes a subscription."""
        self.subscription_handler.handle_command({'action': 'UNSUBSCRIPTION', 'stream_filter': data['stream_filter'], 'id': data['id']}, self.sub_list)

    def cleanup(self):
        """Signals the main thread to stop."""
        self.running = False


