        self.sub_list = {}
        self.sub_list['control'] = self.sub_list['status'] = SubscriptionHandlerThread(self.sub_list, logger)
        self.sub_list['control'].running = True
        self.sub_list['status'].running = True
        self.sub_list['control'].start()
        self.sub_list['status'].start()

