        """Handles incoming messages on a ZMQ socket."""
        if stream_filter == 'control':
            self.sub_list['control'].process_data(data)
        elif stream_filter == 'status':
            self.sub_list['status'].process_data(data)
        else:
            self.logger.warning(f"Unknown stream filter: {stream_filter}")
            return

    def cleanup(self):
        """Closes the ZMQ sockets."""
        self.sub_list['control'].running = False
        self.sub_list['status'].running = False
        self.sub_list['control'].sub_list['control'].remove_subscription(self.sub_list['control'])
        self.sub_list['status'].sub_list['status'].remove_subscription(self.sub_list['status'])
        self.sub_list['control'].sub_list['status'].remove_subscription(self.sub_list['control'])
        self.sub_list['control'].sub_list['status'].remove_subscription(self.sub_list['status'])

