import random
import time
import json
from gpiozero import LED # Import gpiozero, even though we're not using GPIO directly

# Define the JSON file to store voice actions
VOICE_ACTIONS_FILE = 'voice_actions.json'

def generate_audio_frame():
    """Simulates an audio frame with a random energy level."""
    return random.randint(0, 9)

def transcribe_audio_frame(frame_energy):
    """Transcribes the simulated audio frame into a command keyword."""
    # Map energy level to command keyword (0: water, 1: stop, 2: status)
    if frame_energy == 0:
        return 'water'
    elif frame_energy == 1:
        return 'stop'
    else:
        return 'status'

def execute_action(action):
    """Executes a simulated farm action based on the transcribed command."""
    if action == 'open_valve':
        print('Opening water valve')
    elif action == 'close_valve':
        print('Closing water valve')
    elif action == 'report':
        print('System status: Water valve is open')

def save_actions(actions):
    """Saves the list of executed actions to a JSON file."""
    try:
        with open(VOICE_ACTIONS_FILE, 'w') as f:
            json.dump(actions, f)
        print(f'Voice actions saved to {VOICE_ACTIONS_FILE}')
    except Exception as e:
        print(f'Error saving actions to file: {e}')

def load_actions():
    """Loads the list of executed actions from a JSON file."""
    try:
        with open(VOICE_ACTIONS_FILE, 'r') as f:
            actions = json.load(f)
        return actions
    except FileNotFoundError:
        print(f'Actions file not found: {VOICE_ACTIONS_FILE}')
        return []
    except Exception as e:
        print(f'Error loading actions from file: {e}')
        return []

def main():
    """Main function to simulate voice recognition and save actions."""
    actions = []
    try:
        # Simulate voice recognition for 6 frames
        for i in range(6):
            frame_energy = generate_audio_frame()
            transcribed_word = transcribe_audio_frame(frame_energy)
            print(f'Frame {i+1}: {transcribed_word} (Energy: {frame_energy})')
            action = execute_action(transcribed_word)
            actions.append(action)
            time.sleep(1)

        # Save the actions to the JSON file
        save_actions(actions)

    except Exception as e:
        print(f'An error occurred: {e}')
    finally:
        # Ensure actions are saved even if an error occurs
        save_actions(actions)

if __name__ == "__main__":
    main()

