import time
import logging
import signal
import sys
from gpiozero import Motor, DigitalOutputDevice, exc

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Define GPIO pins (BCM numbering)
LEFT_MOTOR_FORWARD_PIN = 17
LEFT_MOTOR_BACKWARD_PIN = 18
LEFT_MOTOR_ENABLE_PIN = 12
RIGHT_MOTOR_FORWARD_PIN = 22
RIGHT_MOTOR_BACKWARD_PIN = 23
RIGHT_MOTOR_ENABLE_PIN = 13

# Define motor objects
left_motor = None
right_motor = None

# Define chassis controller class
class ChassisController:
    def __init__(self):
        """Initializes the chassis controller."""
        try:
            self.left_motor = Motor(forward=LEFT_MOTOR_FORWARD_PIN, backward=LEFT_MOTOR_BACKWARD_PIN, enable=LEFT_MOTOR_ENABLE_PIN)
            self.right_motor = Motor(forward=RIGHT_MOTOR_FORWARD_PIN, backward=RIGHT_MOTOR_BACKWARD_PIN, enable=RIGHT_MOTOR_ENABLE_PIN)
            self.left_motor.enable(DigitalOutputDevice(LEFT_MOTOR_ENABLE_PIN))
            self.right_motor.enable(DigitalOutputDevice(RIGHT_MOTOR_ENABLE_PIN))
            logging.info("Chassis controller initialized successfully.")
        except exc.GPIODeviceError as e:
            logging.error(f"Error initializing GPIO: {e}")
            sys.exit(1)
        except Exception as e:
            logging.error(f"An unexpected error occurred during initialization: {e}")
            sys.exit(1)

    def drive_forward(self, speed_fraction):
        """Drives the chassis forward at the given speed."""
        try:
            self.left_motor.forward(speed_fraction)
            self.right_motor.forward(speed_fraction)
            logging.info("Chassis driving forward.")
        except Exception as e:
            logging.error(f"Error driving forward: {e}")

    def turn_left(self, speed_fraction):
        """Turns the chassis left at the given speed."""
        try:
            self.left_motor.backward(speed_fraction)
            self.right_motor.forward(speed_fraction)
            logging.info("Chassis turning left.")
        except Exception as e:
            logging.error(f"Error turning left: {e}")

    def turn_right(self, speed_fraction):
        """Turns the chassis right at the given speed."""
        try:
            self.left_motor.forward(speed_fraction)
            self.right_motor.backward(speed_fraction)
            logging.info("Chassis turning right.")
        except Exception as e:
            logging.error(f"Error turning right: {e}")

    def stop_all(self):
        """Stops both motors."""
        try:
            self.left_motor.stop()
            self.right_motor.stop()
            logging.info("Chassis stopped.")
        except Exception as e:
            logging.error(f"Error stopping motors: {e}")


def read_tilt_angles():
    """Simulates reading tilt angles from an IMU."""
    # Replace with actual IMU reading code if available
    # For simulation, return a fixed set of angles
    return [25, -25, 0, 30, -15, 40, -30, 10]


def control_chassis(chassis_controller, tilt_angles):
    """Controls the chassis based on tilt angles."""
    try:
        for tilt in tilt_angles:
            logging.info(f"Reading tilt angle: {tilt}")

            if tilt > 20:
                chassis_controller.drive_forward(0.5)
            elif tilt < -20:
                chassis_controller.turn_left(0.5)
            else:
                chassis_controller.stop_all()

    except Exception as e:
        logging.error(f"Error during chassis control: {e}")


def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM signals for graceful shutdown."""
    logging.info("Received signal, shutting down gracefully...")
    chassis_controller.stop_all()
    sys.exit(0)


def main():
    """Main function to run the chassis control program."""
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        chassis_controller = ChassisController()
        control_chassis(chassis_controller, read_tilt_angles())

    except Exception as e:
        logging.error(f"An unhandled error occurred: {e}")
        sys.exit(1)

    finally:
        if left_motor:
            left_motor.close()
        if right_motor:
            right_motor.close()
        logging.info("GPIO resources released.")


if __name__ == "__main__":
    main()

