                chassis_controller.drive_forward(0.5)
            elif tilt < -20:
                chassis_controller.turn_left(0.5)
            else:
                chassis_controller.stop_all()

    except Exception as e:
        logging.error(f"Error during chassis control: {e}")


def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM signals for graceful shutdown."""
    logging.info("Received signal, shutting down gracefully...")
    chassis_controller.stop_all()
    sys.exit(0)


def main():
    """Main function to run the chassis control program."""
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        chassis_controller = ChassisController()
        control_chassis(chassis_controller, read_tilt_angles())

    except Exception as e:
        logging.error(f"An unhandled error occurred: {e}")
        sys.exit(1)

    finally:
        if left_motor:
            left_motor.close()
        if right_motor:
            right_motor.close()
        logging.info("GPIO resources released.")


if __name__ == "__main__":
