from gpiozero import OutputDevice, Servo
import time

class Laser:
    def __init__(self, laser_pin=17):
        try:
            self.laser = OutputDevice(laser_pin)
        except Exception as e:
            print(f"Error initializing laser: {e}")
            self.laser = None

    def on(self):
        if self.laser:
            self.laser.on()
            print("Laser ON")

    def off(self):
        if self.laser:
            self.laser.off()
            print("Laser OFF")

    def close(self):
        if self.laser:
            self.laser.close()
            print("Laser closed")

class Aim:
    def __init__(self, ld, sd):
        try:
            self.horiz = Servo(18)
            self.ver = Servo(19)
            self.hp = [0.0, 0.15, 0.30, 0.45, 0.60, 0.75, 0.90, 1.05, 1.20, 1.35]
            self.vp = [0.15, 0.30, 0.45, 0.60, 0.75, 0.90, 1.05, 1.20, 1.35, 1.50]
            self.ld = ld
            self.sd = sd
        except Exception as e:
            print(f"Error initializing aim: {e}")
            self.horiz = None
            self.ver = None

    def aim(self, nums):
        if not self.horiz or not self.ver:
            print("Aim not initialized")
            return
        try:
            for num in nums:
                self.move_servo(num)
                time.sleep(self.sd / 2)
                self.laser.on()
                time.sleep(self.ld)
                self.laser.off()
                self.move_servo(10)  # Return to neutral
                time.sleep(self.sd / 2)
        except KeyboardInterrupt:
            print("Interrupted")
        finally:
            self.laser.off()
            self.horiz.close()
            self.ver.close()

    def move_servo(self, num):
        if not self.horiz or not self.ver:
            return
        try:
            if num == 1:
                self.horiz.value = self.hp[9]
                self.ver.value = self.vp[8]
            elif num == 2:
                self.horiz.value = self.hp[8]
                self.ver.value = self.vp[7]
            # ... (rest of the numbers)
            else:
                self.horiz.value = self.hp[num - 1]
                self.ver.value = self.vp[num - 1]
        except Exception as e:
            print(f"Error moving servo: {e}")

if __name__ == "__main__":
    ld = 0.2
    sd = 0.3
    a = Aim(ld, sd)
    l = Laser()
    target_numbers = [1, 2, 3, 4, 5]
    try:
        a.aim(target_numbers)
    finally:
        l.close()
        a.close()

