from gpiozero import PWMOutputDevice, OutputDevice
import time

# Motor driver pin assignments (BCM numbering)
MOTOR_PWM_PIN = 17
MOTOR_DIRECTION_PIN = 22

# Motor control constants
PWM_FREQUENCY = 100
FORWARD_DIRECTION = 1
REVERSE_DIRECTION = 0

def initialize_motor():
    """Initialize the motor driver pins and return a PWM device."""
    try:
        # Create PWMOutputDevice for speed control
        pwm_motor = PWMOutputDevice(MOTOR_PWM_PIN, frequency=PWM_FREQUENCY)
        # Create OutputDevice for direction control
        direction_control = OutputDevice(MOTOR_DIRECTION_PIN, initial_value=FORWARD_DIRECTION)
        return pwm_motor
    except Exception as e:
        print(f"Motor initialization error: {e}")
        return None

def set_motor_direction(pwm_device, forward_state):
    """Set the motor direction."""
    try:
        direction_control = OutputDevice(MOTOR_DIRECTION_PIN, initial_value=forward_state)
        pwm_device.value = 0  # Ensure no speed while switching direction
        direction_control.value = forward_state
        time.sleep(0.1) # Allow time for the direction to change
        pwm_device.value = 100 # Resume full speed
    except Exception as e:
        print(f"Motor direction error: {e}")

def run_motor_cycle(pwm_device, cycle_count=3):
    """Run the motor through a series of speed cycles."""
    try:
        for cycle_index in range(cycle_count):
            if cycle_index % 3 == 0:
                set_motor_direction(pwm_device, FORWARD_DIRECTION)
            elif cycle_index % 3 == 1:
                set_motor_direction(pwm_device, REVERSE_DIRECTION)
            else:
                set_motor_direction(pwm_device, FORWARD_DIRECTION)
            time.sleep(1)
    except Exception as e:
        print(f"Motor cycle error: {e}")

def cleanup_motor(pwm_device):
    """Stop the motor and release resources."""
    try:
        pwm_device.value = 0
        pwm_device.close()
    except Exception as e:
        print(f"Motor cleanup error: {e}")

def main():
    """Main function to run the motor control loop."""
    pwm_motor = initialize_motor()
    if pwm_motor is None:
        return

    try:
        while True:
            run_motor_cycle(pwm_motor)
    except KeyboardInterrupt:
        print("Motor control interrupted by user.")
    except Exception as e:
        print(f"Unexpected error: {e}")
    finally:
        cleanup_motor(pwm_motor)

if __name__ == "__main__":
    main()

