import time
import curses
import sys
import os
from Adafruit_CircuitPython_PCA9685 import PCA9685

# Constants for PWM control
PWM_FREQUENCY = 60
THROTTLE_STOP_VALUE = 400
STEERING_CENTER_VALUE = 500
PWM_CHANNEL_ESC = 0
PWM_CHANNEL_STEERING = 1

# Global variables
esc_pwm = None
curses_screen = None


def initialize_curses():
    """Initializes the curses screen for keyboard input."""
    global curses_screen
    curses_screen = curses.initscr()
    curses_screen.noecho()
    curses_screen.cbreak()
    curses_screen.keypad(True)
    curses_screen.notimeout(true)


def cleanup_curses():
    """Restores the terminal settings after using curses."""
    if curses_screen:
        curses_screen.keypad(0)
        curses_screen.echo()
        curses_screen.endwin()


def initialize_pwm():
    """Initializes the PCA9685 PWM controller."""
    global esc_pwm
    try:
        esc_pwm = PCA9685(address=0x40, busnum=1)
        esc_pwm.set_pwm_freq(PWM_FREQUENCY)
    except Exception as e:
        print(f"Error initializing PCA9685: {e}")
        cleanup_curses()
        sys.exit(1)


def set_esc_speed(speed):
    """Sets the ESC speed.

    Args:
        speed: A value between 200 and 800.
    """
    try:
        esc_pwm.set_pwm(PWM_CHANNEL_ESC, 0, speed)
    except Exception as e:
        print(f"Error setting ESC speed: {e}")


def set_steering_angle(angle):
    """Sets the steering angle.

    Args:
        angle: A value between 380 and 620.
    """
    try:
        esc_pwm.set_pwm(PWM_CHANNEL_STEERING, 0, angle)
    except Exception as e:
        print(f"Error setting steering angle: {e}")


def calibrate_esc():
    """Calibrates the ESC by ramping throttle up and down."""
    print("Calibrating ESC...")
    set_esc_speed(200)
    time.sleep(0.1)
    for value in range(200, 801, 20):
        set_esc_speed(value)
        time.sleep(0.1)
    for value in range(800, -1, -20):
        set_esc_speed(value)
        time.sleep(0.1)
    set_esc_speed(400)
    print("ESC calibration complete.")


def main():
    """Main function to control the RC car."""
    global esc_pwm, curses_screen

    initialize_curses()
    initialize_pwm()

    try:
        calibrate_esc()
    except Exception as e:
        print(f"Calibration failed: {e}")
        cleanup_curses()
        sys.exit(1)

    set_esc_speed(THROTTLE_STOP_VALUE)
    set_steering_angle(STEERING_CENTER_VALUE)

    while True:
        try:
            char = curses_screen.getch()

            if char == ord('q'):
                set_esc_speed(THROTTLE_STOP_VALUE)
                set_steering_angle(STEERING_CENTER_VALUE)
                print("Car stopped and centered.")
                break

            elif char == ord('x'):
                cleanup_curses()
                sys.exit(0)

            elif char == curses.KEY_UP:
                if set_esc_speed(esc_pwm.pwm_range.max) > THROTTLE_STOP_VALUE:
                    set_esc_speed(esc_pwm.pwm_range.max - 20)
                else:
                    set_esc_speed(esc_pwm.pwm_range.max)

            elif char == curses.KEY_DOWN:
                if set_esc_speed(esc_pwm.pwm_range.min) < THROTTLE_STOP_VALUE:
                    set_esc_speed(esc_pwm.pwm_range.min + 20)
                else:
                    set_esc_speed(esc_pwm.pwm_range.min)

            elif char == curses.KEY_LEFT:
                if set_steering_angle(STEERING_CENTER_VALUE - 20) > 380:
                    set_steering_angle(STEERING_CENTER_VALUE - 20)
                else:
                    set_steering_angle(STEERING_CENTER_VALUE + 20)

            elif char == curses.KEY_RIGHT:
                if set_steering_angle(STEERING_CENTER_VALUE + 20) < 620:
                    set_steering_angle(STEERING_CENTER_VALUE + 20)
                else:
                    set_steering_angle(STEERING_CENTER_VALUE - 20)

        except Exception as e:
            print(f"Error during control: {e}")
            break

        cleanup_curses()
        sys.exit(0)


if __name__ == "__main__":
    main()

