import gpiozero
import time
import logging

# Configure logging for the hydroponics controller
logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s")

# GPIO pins for the nutrient pump and grow light
PUMP_PIN = 20
LIGHT_PIN = 21

# Initialize gpiozero OutputDevice actuators
try:
    pump = gpiozero.OutputDevice(PUMP_PIN)
    light = gpiozero.OutputDevice(LIGHT_PIN)
except Exception as e:
    logging.error("Actuator initialization failed: %s", e)
    pump = None
    light = None


def parse_phrase(phrase):
    """Parse a plain English phrase into a hydroponics control intent."""
    # Lowercase the phrase for case-insensitive matching
    phrase = phrase.lower()
    # Keyword-based matching for known intents
    if "pump on" in phrase:
        return "pump_on"
    elif "pump off" in phrase:
        return "pump_off"
    elif "light toggle" in phrase:
        return "light_toggle"
    elif "light on" in phrase:
        return "light_on"
    elif "light off" in phrase:
        return "light_off"
    else:
        # Unknown intent, log a warning and return None
        logging.warning("Unknown intent: %s", phrase)
        return None


def apply_intent(intent):
    """Apply a hydroponics control intent to the corresponding actuators."""
    if intent == "pump_on":
        if pump:
            pump.on()
            logging.info("Nutrient pump turned on")
    elif intent == "pump_off":
        if pump:
            pump.off()
            logging.info("Nutrient pump turned off")
    elif intent == "light_toggle":
        if light:
            light.toggle()
            logging.info("Grow light toggled")
    elif intent == "light_on":
        if light:
            light.on()
            logging.info("Grow light turned on")
    elif intent == "light_off":
        if light:
            light.off()
            logging.info("Grow light turned off")


def main():
    """Main function to parse phrases and apply hydroponics intents."""
    try:
        # Process a list of test phrases for demonstration
        for phrase in ["turn the pump on", "switch the light", "turn pump off", "unknown command"]:
            intent = parse_phrase(phrase)
            if intent:
                apply_intent(intent)
            time.sleep(1)
    except KeyboardInterrupt:
        logging.info("Script interrupted by user")
    finally:
        # Ensure actuators are off on exit
        if pump:
            pump.close()
        if light:
            light.close()
        logging.info("Hydroponics controller shutting down")


if __name__ == "__main__":
    main()

