import smbus2
import time
import csv
import sys

# INA219 I2C address
INA219_ADDRESS = 0x40

# Shunt resistor value (Ohms)
SHUNT_RESISTOR = 0.1

# Power threshold (Watts)
POWER_THRESHOLD = 45.0

# Initialize I2C bus
try:
    bus = smbus2.SMBus(1)
except FileNotFoundError:
    print("Error: I2C bus not found. Please enable I2C on your Raspberry Pi.")
    sys.exit(1)
except Exception as e:
    print(f"Error initializing I2C bus: {e}")
    sys.exit(1)

# Function to read raw data from the INA219
def read_raw_data(register):
    try:
        return bus.read_word_data(INA219_ADDRESS, register)
    except Exception as e:
        print(f"Error reading register {register}: {e}")
        return None

# Function to convert raw data to voltage or current
def convert_to_voltage(raw_data):
    return (raw_data / 32767.0) * 5.0

def convert_to_current(raw_data):
    return (raw_data / 32767.0) * SHUNT_RESISTOR

# Function to read bus voltage
def read_bus_voltage():
    raw_data = read_raw_data(0x02)
    if raw_data is None:
        return None
    return convert_to_voltage(raw_data)

# Function to read shunt voltage
def read_shunt_voltage():
    raw_data = read_raw_data(0x01)
    if raw_data is None:
        return None
    return convert_to_voltage(raw_data)

# Function to read current
def read_current():
    raw_data = read_raw_data(0x03)
    if raw_data is None:
        return None
    return convert_to_current(raw_data)

# Function to read power
def read_power():
    raw_data = read_raw_data(0x03)
    if raw_data is None:
        return None
    return (raw_data / 32767.0) * (SHUNT_RESISTOR ** 2) * 1000.0

# Function to write data to CSV file
def write_to_csv(timestamp, bus_voltage, current, power):
    try:
        with open('device_power.csv', 'a', newline='') as csvfile:
            writer = csv.writer(csvfile)
            writer.writerow([timestamp, bus_voltage, current, power])
    except Exception as e:
        print(f"Error writing to CSV file: {e}")

# Main loop
try:
    with open('device_power.csv', 'w', newline='') as csvfile:
        writer = csv.writer(csvfile)
        writer.writerow(['Timestamp', 'Bus Voltage (V)', 'Current (A)', 'Power (W)'])

        for _ in range(60):
            timestamp = time.strftime('%Y-%m-%d %H:%M:%S')
            bus_voltage = read_bus_voltage()
            current = read_current()
            power = read_power()

            if bus_voltage is not None and current is not None and power is not None:
                print(f"{timestamp}, {bus_voltage:.2f}, {current:.2f}, {power:.2f}")
                write_to_csv(timestamp, bus_voltage, current, power)

                if power > POWER_THRESHOLD:
                    print("Alert: Power consumption exceeds threshold!")

            time.sleep(1)

except KeyboardInterrupt:
    print("Program terminated by user.")

finally:
    bus.close()
    print("I2C bus closed.")

