import smbus2
import time
import datetime
import signal
import sys
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants for RTC register addresses (DS1338)
REG_SECONDS = 0x00
REG_MINUTES = 0x01
REG_HOURS = 0x02
REG_DATE = 0x04
REG_MONTH = 0x05
REG_YEAR = 0x06

# I2C bus setup
I2C_BUS = 1  # Default I2C bus on Raspberry Pi
I2C_ADDRESS = 0x68  # Default DS1338 I2C address

# Global bus variable
bus = None

def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM signals for graceful shutdown."""
    logging.info('Shutting down gracefully...')
    cleanup()
    sys.exit(0)

def cleanup():
    """Releases resources and performs cleanup operations."""
    global bus
    if bus:
        try:
            bus.close()
            logging.info('I2C bus closed.')
        except Exception as e:
            logging.error(f"Error closing I2C bus: {e}")
    logging.info('Cleanup complete.')

def read_register(register):
    """Reads a single byte from the specified register."""
    try:
        return bus.read_byte_data(I2C_ADDRESS, register)
    except OSError as e:
        logging.error(f"I2C read error: {e}")
        return None

def write_register(register, value):
    """Writes a byte to the specified register."""
    try:
        bus.write_byte_data(I2C_ADDRESS, register, value)
    except OSError as e:
        logging.error(f"I2C write error: {e}")

def bcd_to_int(bcd):
    """Converts a BCD value to an integer."""
    try:
        return (bcd >> 4) * 10 + (bcd & 0x0F)
    except TypeError:
        logging.error("Invalid BCD value provided.")
        return None

def int_to_bcd(n):
    """Converts an integer to BCD format."""
    if not 0 <= n <= 99:
        raise ValueError("Integer must be between 0 and 99 for BCD conversion.")
    return (n // 10 << 4) | (n % 10)

def read_time_register(register):
    """Reads and converts a time register value (seconds, minutes, hours)."""
    value = read_register(register)
    if value is None:
        return None

    if register == REG_SECONDS:
        return bcd_to_int(value) # Seconds are stored as integer
    elif register == REG_MINUTES:
        return bcd_to_int(value)
    elif register == REG_HOURS:
        # Hours are stored as BCD, but we assume 24-hour format.
        # Bit 6 is a century bit, so we clear it to get the correct hour.
        value &= 0x67  # Clear century bit (mask 0x80)
        return bcd_to_int(value)
    else:
        return None

def read_datetime():
    """Reads the current date and time from the RTC."""
    try:
        seconds = read_time_register(REG_SECONDS)
        minutes = read_time_register(REG_MINUTES)
        hours = read_time_register(REG_HOURS)
        date = read_time_register(REG_DATE)
        month = read_time_register(REG_MONTH)
        year = read_time_register(REG_YEAR)

        if not all([seconds is not None, minutes is not None, hours is not None, date is not None, month is not None, year is not None]):
            logging.error("Failed to read all time registers.")
            return None

        # Validate year range (adjust 21 for current century)
        if not 0 <= year <= 99:
            logging.warning(f"Year {year} out of range (0-99). Using current year.")
            year = 100 + (time.time() // 31556926) % 100  # Approximate current year

        return datetime.datetime(2000 + year, month, date, hours, minutes, seconds)

    except Exception as e:
        logging.error(f"Error reading datetime: {e}")
        return None

def write_time_register(register, value):
    """Writes a time register value (seconds, minutes, hours)."""
    if value is None:
        return  # Don't write if value is None

    if register == REG_SECONDS:
        write_register(register, int_to_bcd(value)) # Convert to BCD
    elif register == REG_MINUTES:
        write_register(register, int_to_bcd(value))
    elif register == REG_HOURS:
        # Set the hours register to the BCD representation, clearing the century bit.
        write_register(register, (int_to_bcd(hours) & 0x67))
    else:
        return

def write_datetime(dt):
    """Writes the given datetime object to the RTC."""
    try:
        write_time_register(REG_SECONDS, dt.second)
        write_time_register(REG_MINUTES, dt.minute)
        write_time_register(REG_HOURS, dt.hour)  # Hours are stored as BCD
        write_register(REG_DATE, dt.isoweekday())  # Date is stored as day of the week
        write_register(REG_MONTH, dt.month)
        write_register(REG_YEAR, dt.year % 100)  # Year is stored as last two digits
    except Exception as e:
        logging.error(f"Error writing datetime: {e}")

def main():
    """Main function to read and write time data."""
    global bus
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        bus = smbus2.SMBus(I2C_BUS)
        logging.info("RTC initialized successfully.")
    except OSError as e:
        logging.error(f"Failed to initialize I2C bus: {e}")
        sys.exit(1)

    try:
        while True:
            current_time = read_datetime()
            if current_time:
                logging.info(f"Current time: {current_time.strftime('%Y-%m-%d %H:%M:%S')}")

                user_input = input("Enter new time (hh:mm:ss), or press Enter to cancel: ")
                if user_input:
                    try:
                        hours, minutes, seconds = map(int, user_input.split(':'))
                        write_datetime(datetime.datetime.now()) # Set current time as base
                        write_time_register(REG_HOURS, hours)
                        write_time_register(REG_MINUTES, minutes)
                        write_time_register(REG_SECONDS, seconds)
                        logging.info(f"Time set to {user_input}")
                    except ValueError:
                        logging.error("Invalid time format. Please use HH:MM:SS.")
            else:
                logging.info("No datetime to display.")

    except KeyboardInterrupt:
        logging.info("Exiting program.")
    finally:
        cleanup()

if __name__ == "__main__":
    main()

