#!/usr/bin/env python3
# -*- coding: utf-8 -*-

"""
DS1338 Real-Time Clock Driver for Raspberry Pi

This module provides a robust and efficient driver for the DS1338 RTC chip.
"""

import smbus2 as smbus
from datetime import datetime
import contextlib

class DS1338Error(Exception):
    """Custom exception for DS1338 errors."""
    pass

def _bcd_to_int(bcd_value):
    """Decode a 2x4bit BCD value to an integer."""
    try:
