        self.next_id += 1
        return {'id': new_id, 'name': name, 'done': done}


class SerialException(Exception):
    """Custom exception for serial communication errors."""
    pass


@app.errorhandler(500)
def internal_server_error(e):
    """Handles internal server errors."""
    logging.error(f"Internal Server Error: {e}")
    return Response(str(e), mimetype='text/plain')


@app.errorhandler(504)
def gateway_timeout(e):
    """Handles gateway timeout errors."""
    logging.warning(f"Gateway Timeout Error: {e}")
    return Response("Service Unavailable", mimetype='text/plain')


@app.errorhandler(502)
def bad_gateway(e):
    """Handles bad gateway errors."""
    logging.warning(f"Bad Gateway Error: {e}")
    return Response("Invalid Gateway", mimetype='text/plain')


@app.route('/')
def health_check():
    """Returns a health check response."""
    return Response('OK', mimetype='text/plain')


@app.route('/version')
def get_device_version():
    """Retrieves the device version information via serial communication."""
    communicator = SerialCommunicator(DEFAULT_SERIAL_PORT, DEFAULT_BAUDRATE)
    try:
        communicator.open()
        response = communicator.receive_line()
        if response:
            version_lines = response.split('\n')
            if version_lines and version_lines[0].startswith('Instrument'):
                version = [line.strip() for line in version_lines]
                if version and version[4] == '*IDN?':
                    try:
                        instrument_id = int(version[2].split('=')[1].split("'")[0])
                        firmware_version = version[3].split('=')[1].split("'")[0]
                        return jsonify({'firmware': firmware_version})
                    except (ValueError, IndexError) as e:
                        logging.error(f"Error parsing version information: {e}")
                        return jsonify({'error': str(e)})

        return jsonify({'error': 'Failed to retrieve device version'})

    except SerialException as e:
        logging.error(f"Serial communication error: {e}")
        return jsonify({'error': str(e)})

    except Exception as e:
        logging.error(f"Unexpected error in /version: {e}")
        return jsonify({'error': str(e)})

    finally:
        if communicator.ser:
            communicator.ser.close()


@app.route('/data')
def get_all_data():
    """Returns all data items."""
    return jsonify(DataManager().get_all())


@app.route('/data/<int:item_id>')
def get_data_item(item_id):
    """Returns a specific data item."""
    item = DataManager().get_by_id(item_id)
    if item:
        return jsonify(item)
    else:
        return Response("Item not found", mimetype='text/plain', status=404)


@app.route('/data', methods=['POST'])
def create_data_item():
    """Creates a new data item."""
    try:
        new_item = request.get_json()
        if not new_item or 'name' not in new_item or 'done' not in new_item:
            raise ValueError("Missing 'name' or 'done' in JSON payload.")
        new_item['id'] = DataManager().next_id
        DataManager().create(new_item['name'], new_item['done'])
        return jsonify(new_item), 201
    except (ValueError, KeyError) as e:
        logging.error(f"Invalid data item creation: {e}")
        abort(400, description=str(e))
    except Exception as e:
        logging.error(f"Unexpected error in /data: {e}")
        abort(500, description=str(e))


def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM signals for graceful shutdown."""
    logging.info(f"Received signal {sig}. Shutting down...")
    global serial_port, serial_instance
    if serial_port and serial_instance:
        serial_port.close()
        serial_instance.close()
    GPIO.cleanup()  # Clean up GPIO on exit
    app.shutdown()


if __name__ == '__main__':
    # Register signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Start the Flask development server
    try:
        app.run(host='0.0.0.0', port=SERVER_PORT, debug=False, use_reloader=False)
    except Exception as e:
        logging.critical(f"Failed to start server: {e}")
    finally:
        logging.info("Exiting application.")

