import json
import time
from threading import Thread
from flask import Flask, Response, request, jsonify, abort
from serial import Serial, SerialException

app = Flask(__name__)
store = [{"id": 1, "name": "CHIPS", "done": False}, {"id": 2, "name": "garden", "done": False}]

def get_serial_port():
    """Returns a Serial port object. Handles connection errors."""
    try:
        ser = Serial("/dev/ttyUSB0", 9600, timeout=0.5)
        ser.write(b"*IDN?\n")
        time.sleep(0.1)
        return ser
    except SerialException as e:
        print(f"Serial connection error: {e}")
        return None

@app.route('/version', methods=['GET'])
def version():
    """Returns the application version information."""
    ser = get_serial_port()
    if ser:
        try:
            response = ser.read(1000)
            return Response(response, mimetype='text/html')
        finally:
            ser.close()
    else:
        return Response("Serial port not available", mimetype='text/html', status=503)

@app.route('/getdata', methods=['GET'])
