def get_item(item_id):
    """Returns a specific item from the data store as JSON."""
    item = next((item for item in store if item["id"] == item_id), None)
    if item:
        return jsonify(item)
    else:
        abort(404)

@app.route('/getpost/<int:item_id>/<name>', methods=['GET'])
def add_item(item_id, name):
    """Adds an item to the data store and returns the updated store as JSON."""
    store.append({"id": store[-1]['id'] + 1 if store else 1, "name": name, "done": False})
    return jsonify(store)

@app.route('/postjson', methods=['POST'])
def post_json():
    """Handles POST requests with JSON data."""
    try:
        if "application/json" in request.headers.get("Content-Type", ""):
            data = request.get_json()
        else:
            data = request.form.to_dict()  # Handle form data

        if not data or "item" not in data:
            abort(400, "Missing 'item' key in request body")

        item_id = data["item"]  # Assuming 'item' contains the item_id
        name = data.get("name", "")  # Get 'name', defaulting to empty string

        new_id = store[-1]['id'] + 1 if store else 1
        store.append({"id": new_id, "name": name, "done": False})
        return jsonify(store)

